using System.Collections.Generic;

public class Solution {
    private void Collect(TreeNode node, List<int> path, List<List<int>> answer) {
        if (node == null) {
            return;
        }

        path.Add(node.data);

        if (node.left == null && node.right == null) {
            answer.Add(new List<int>(path));
            return;
        }

        if (node.left != null) {
            List<int> leftPath = new List<int>(path);
            Collect(node.left, leftPath, answer);
        }

        if (node.right != null) {
            List<int> rightPath = new List<int>(path);
            Collect(node.right, rightPath, answer);
        }
    }

    public List<List<int>> AllRootToLeaf(TreeNode root) {
        List<List<int>> answer = new List<List<int>>();
        Collect(root, new List<int>(), answer);
        return answer;
    }
}
