    }

    private void GetAllResults(TreeNode root, List<List<int>> result, List<int> currItem) {

        if(root == null) return;
        currItem.Add(root.data);

        // check if curr node is leaf
        if(root.left == null && root.right == null) {
            result.Add(new List<int>(currItem));             
        }
        else {
            GetAllResults(root.left, result, currItem);
            GetAllResults(root.right, result, currItem);
        }

        // backtrack
        currItem.RemoveAt(currItem.Count - 1);
    }

}
